-- P22.catalog.seed: 400 sourced generic outpatient formulations, no schema changes.
-- Source: FDA NDC/openFDA, retrieved 2026-11-27; see docs/database/DRUG_CATALOG.md.
-- Manifest: backend/scripts/data/outpatient-drugs-openfda.json, SHA256 44f7186a53b1ea3db0ed622224b339d008bee9af0d961e8ce83d5fe7df005b13
-- Source ingredient/strength pairs are preserved in that manifest.
-- No price, inventory, treatment dose, patient data, UPDATE, DELETE or MERGE.
-- Flyway owns the transaction. Existing rows (including inactive rows) are retained.

DECLARE @SeedDrug TABLE (
    code varchar(40) PRIMARY KEY,
    name nvarchar(200) NOT NULL,
    ingredient nvarchar(300) NOT NULL,
    strength nvarchar(100) NOT NULL,
    dosage_form nvarchar(100) NOT NULL,
    unit nvarchar(50) NOT NULL,
    is_active bit NOT NULL
);


-- A different medication under a reserved seed code is a conflict, never overwritten.
IF EXISTS (
    SELECT 1 FROM dbo.Drug d JOIN @SeedDrug s ON s.code=d.code
    WHERE NOT (REPLACE(REPLACE(REPLACE(COALESCE(d.ingredient,N''),N' ',N''),NCHAR(9),N''),NCHAR(160),N'') COLLATE Latin1_General_100_CI_AI=REPLACE(REPLACE(REPLACE(COALESCE(s.ingredient,N''),N' ',N''),NCHAR(9),N''),NCHAR(160),N'') COLLATE Latin1_General_100_CI_AI AND
        REPLACE(REPLACE(REPLACE(COALESCE(d.strength,N''),N' ',N''),NCHAR(9),N''),NCHAR(160),N'') COLLATE Latin1_General_100_CI_AI=REPLACE(REPLACE(REPLACE(COALESCE(s.strength,N''),N' ',N''),NCHAR(9),N''),NCHAR(160),N'') COLLATE Latin1_General_100_CI_AI AND
        REPLACE(REPLACE(REPLACE(COALESCE(d.dosage_form,N''),N' ',N''),NCHAR(9),N''),NCHAR(160),N'') COLLATE Latin1_General_100_CI_AI=REPLACE(REPLACE(REPLACE(COALESCE(s.dosage_form,N''),N' ',N''),NCHAR(9),N''),NCHAR(160),N'') COLLATE Latin1_General_100_CI_AI AND
        REPLACE(REPLACE(REPLACE(COALESCE(d.unit,N''),N' ',N''),NCHAR(9),N''),NCHAR(160),N'') COLLATE Latin1_General_100_CI_AI=REPLACE(REPLACE(REPLACE(COALESCE(s.unit,N''),N' ',N''),NCHAR(9),N''),NCHAR(160),N'') COLLATE Latin1_General_100_CI_AI)
)
    THROW 51021, 'Drug seed code conflicts with existing data; review without overwriting.', 1;

SELECT s.code,s.name,s.ingredient,s.strength,s.dosage_form,s.unit,s.is_active
FROM @SeedDrug s
WHERE NOT EXISTS (SELECT 1 FROM dbo.Drug d WITH (UPDLOCK,HOLDLOCK) WHERE d.code=s.code)
  AND NOT EXISTS (
    SELECT 1 FROM dbo.Drug d WITH (UPDLOCK,HOLDLOCK)
    WHERE REPLACE(REPLACE(REPLACE(COALESCE(d.ingredient,N''),N' ',N''),NCHAR(9),N''),NCHAR(160),N'') COLLATE Latin1_General_100_CI_AI=REPLACE(REPLACE(REPLACE(COALESCE(s.ingredient,N''),N' ',N''),NCHAR(9),N''),NCHAR(160),N'') COLLATE Latin1_General_100_CI_AI AND
        REPLACE(REPLACE(REPLACE(COALESCE(d.strength,N''),N' ',N''),NCHAR(9),N''),NCHAR(160),N'') COLLATE Latin1_General_100_CI_AI=REPLACE(REPLACE(REPLACE(COALESCE(s.strength,N''),N' ',N''),NCHAR(9),N''),NCHAR(160),N'') COLLATE Latin1_General_100_CI_AI AND
        REPLACE(REPLACE(REPLACE(COALESCE(d.dosage_form,N''),N' ',N''),NCHAR(9),N''),NCHAR(160),N'') COLLATE Latin1_General_100_CI_AI=REPLACE(REPLACE(REPLACE(COALESCE(s.dosage_form,N''),N' ',N''),NCHAR(9),N''),NCHAR(160),N'') COLLATE Latin1_General_100_CI_AI AND
        REPLACE(REPLACE(REPLACE(COALESCE(d.unit,N''),N' ',N''),NCHAR(9),N''),NCHAR(160),N'') COLLATE Latin1_General_100_CI_AI=REPLACE(REPLACE(REPLACE(COALESCE(s.unit,N''),N' ',N''),NCHAR(9),N''),NCHAR(160),N'') COLLATE Latin1_General_100_CI_AI
  );
